   106  void otPlatAlarmMilliStartAt(otInstance *aInstance, uint32_t aT0, uint32_t aDt)
   107  {
   108      OT_UNUSED_VARIABLE(aInstance);
   109
   110      sAlarmMilli.fire      = (aT0 + aDt) * 1000;
   111      sAlarmMilli.isRunning = true;
   112  }
   113
   114  void otPlatAlarmMilliStop(otInstance *aInstance)
   115  {
   116      OT_UNUSED_VARIABLE(aInstance);
   117
   118      sAlarmMilli.isRunning = false;
   119  }
